contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address a, address b, uint256 v, uint256 supply) public {
        require(a != address(0) && b != address(0));
        c = address(new C(supply, "t", "s")) == address(0) ? c : c;
        require(v > 0 && v <= supply);
        require(a != b);
        bool reverted;
        c.transfer(b, v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted || (c.balanceOf(b) == v && c.totalSupply() == supply));
    }
    receive() external payable {}
}

