pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address a, address b, uint256 v, uint256 supply) internal {
        vm.assume(a != address(0) && b != address(0));
        c = address(new ERCDDAToken(supply, "t", "s")) == address(0) ? c : c;
        vm.assume(v > 0 && v <= supply);
        vm.assume(a != b);
        bool reverted;
        try c.transfer(b, v) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted || (c.balanceOf(b) == v && c.totalSupply() == supply));
    }

    function testFuzz_run(address a, address b, uint256 v, uint256 supply) public {
        vm.assume(a.code.length == 0 && uint160(a) > 0xffff && a != address(this) && a != address(c) && a != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && a != 0x000000000000000000636F6e736F6c652e6c6f67 && a != 0x4e59b44847b379578588920cA78FbF26c0B4956C && a != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(b.code.length == 0 && uint160(b) > 0xffff && b != address(this) && b != address(c) && b != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && b != 0x000000000000000000636F6e736F6c652e6c6f67 && b != 0x4e59b44847b379578588920cA78FbF26c0B4956C && b != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(a, b, v, supply);
    }

    receive() external payable {}
}
